using UnityEngine;
using UnityEngine.UI;

namespace EggRescue
{
    /// <summary>
    /// 主菜单动物的两帧循环。A/B 图来自 Assets/Res/Sprites/StartUi/animalWalk。
    /// </summary>
    public sealed class MenuAnimalFlip : MonoBehaviour
    {
        public const string Folder = "Assets/Res/Sprites/StartUi/animalWalk";

        [SerializeField] Sprite frameA;
        [SerializeField] Sprite frameB;
        [SerializeField] float framesPerSecond = 4f;
        [SerializeField] float phase;

        Image _image;

        void Awake()
        {
            _image = GetComponent<Image>();
            if (_image != null) _image.raycastTarget = false;
#if UNITY_EDITOR
            if (frameA == null || frameB == null)
                TryAssignFromFolder();
#endif
        }

        void Update()
        {
            if (_image == null || frameA == null || frameB == null || framesPerSecond <= 0f) return;
            var step = Mathf.FloorToInt((Time.unscaledTime + phase) * framesPerSecond);
            var sprite = (step & 1) == 0 ? frameA : frameB;
            if (_image.sprite != sprite) _image.sprite = sprite;
        }

#if UNITY_EDITOR
        public void TryAssignFromFolder()
        {
            var image = GetComponent<Image>();
            if (image == null) return;
            var current = image.sprite != null ? image.sprite.name : name;
            var key = GroupKey(current);
            Sprite a = null;
            Sprite b = null;
            var guids = UnityEditor.AssetDatabase.FindAssets("t:Sprite", new[] { Folder });
            for (var i = 0; i < guids.Length; i++)
            {
                var path = UnityEditor.AssetDatabase.GUIDToAssetPath(guids[i]);
                var sprite = UnityEditor.AssetDatabase.LoadAssetAtPath<Sprite>(path);
                if (sprite == null || GroupKey(sprite.name) != key) continue;
                if (sprite.name.Contains("_A_")) a = sprite;
                else if (sprite.name.Contains("_B_")) b = sprite;
            }
            if (a == null || b == null) return;
            frameA = a;
            frameB = b;
            UnityEditor.EditorUtility.SetDirty(this);
        }

        public static string GroupKey(string spriteName)
        {
            if (string.IsNullOrEmpty(spriteName)) return "";
            var a = spriteName.IndexOf("_A_", System.StringComparison.Ordinal);
            var b = spriteName.IndexOf("_B_", System.StringComparison.Ordinal);
            var cut = a >= 0 && b >= 0 ? Mathf.Min(a, b) : Mathf.Max(a, b);
            return cut >= 0 ? spriteName.Substring(0, cut) : spriteName;
        }
#endif
    }
}

using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;

namespace EggRescue.Editor
{
    /// <summary>
    /// 给主菜单 Animals 下的每个动物写入两帧，方便在编辑器里直接看，也让正式包带上贴图引用。
    /// </summary>
    [InitializeOnLoad]
    public static class MenuAnimalFlipBaker
    {
        const string MenuScenePath = "Assets/Scenes/StartMenu.unity";

        static MenuAnimalFlipBaker()
        {
            EditorApplication.delayCall += BakeOpenScene;
        }

        [MenuItem("Tools/Egg Rescue/UI/Bake Animal Walk Frames")]
        public static void BakeMenu()
        {
            var scene = SceneManager.GetActiveScene();
            if (scene.path != MenuScenePath)
                scene = EditorSceneManager.OpenScene(MenuScenePath, OpenSceneMode.Single);
            var count = Bake(scene);
            EditorSceneManager.MarkSceneDirty(scene);
            EditorSceneManager.SaveScene(scene);
            EditorUtility.DisplayDialog("Egg Rescue UI", "已给 " + count + " 个动物写入两帧循环。", "OK");
        }

        static void BakeOpenScene()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode) return;
            var scene = SceneManager.GetActiveScene();
            if (scene.path != MenuScenePath) return;
            var count = Bake(scene);
            if (count > 0) EditorSceneManager.MarkSceneDirty(scene);
        }

        static int Bake(Scene scene)
        {
            var count = 0;
            var roots = scene.GetRootGameObjects();
            for (var i = 0; i < roots.Length; i++)
            {
                var animals = FindDeep(roots[i].transform, "Animals");
                if (animals == null) continue;
                for (var c = 0; c < animals.childCount; c++)
                {
                    var child = animals.GetChild(c);
                    var flip = child.GetComponent<MenuAnimalFlip>();
                    if (flip == null) flip = Undo.AddComponent<MenuAnimalFlip>(child.gameObject);
                    var so = new SerializedObject(flip);
                    var frameA = so.FindProperty("frameA");
                    var frameB = so.FindProperty("frameB");
                    if (frameA.objectReferenceValue != null && frameB.objectReferenceValue != null) continue;
                    flip.TryAssignFromFolder();
                    so.Update();
                    so.FindProperty("phase").floatValue = c * 0.12f;
                    so.ApplyModifiedPropertiesWithoutUndo();
                    EditorUtility.SetDirty(flip);
                    count++;
                }
            }
            return count;
        }

        static Transform FindDeep(Transform root, string target)
        {
            if (root.name == target) return root;
            for (var i = 0; i < root.childCount; i++)
            {
                var found = FindDeep(root.GetChild(i), target);
                if (found != null) return found;
            }
            return null;
        }
    }
}

